#!/usr/bin/env python3
"""Build the Research custom element from its plain JavaScript sources; no framework/runtime dependencies."""
import pathlib,re,json
ROOT=pathlib.Path(__file__).resolve().parents[1]
VERSION='20261118-r7'
template=(ROOT/'research-template.html').read_text()
markup=re.search(r'<main>(.*?)</main>',template,re.S).group(1)+re.search(r'<dialog.*?</dialog>',template,re.S).group(0)
markup='<div class="research-shell"><main>'+markup.split('<dialog')[0]+'</main><dialog'+markup.split('<dialog',1)[1]+'</div>'
source=(ROOT/'analytics.js').read_text()
source='\n'.join(line for line in source.splitlines() if not line.startswith("try{if(localStorage.getItem('amfl-analytics-theme')") and not line.startswith("$('#theme').onclick="))
source=source.replace('const $=s=>document.querySelector(s)','const $=s=>root.querySelector(s)')
source+='\n'+(ROOT/'analytics-tools.js').read_text()+'\n'+(ROOT/'research-extras.js').read_text()+'\n'+(ROOT/'research-tools.js').read_text()
code='''/* Generated by scripts/build_research.py. Source: analytics.js, analytics-tools.js, research-extras.js. */
(function(){
class AMFLResearch extends HTMLElement {
 connectedCallback(){if(this.initialized)return;this.initialized=true;const root=this.attachShadow({mode:'open'});
 root.innerHTML='<link rel="stylesheet" href="/research.css?v=VERSION">'+MARKUP;
 const shell=root.querySelector('.research-shell');const syncTheme=()=>shell.classList.toggle('light',document.documentElement.dataset.theme==='light');syncTheme();
 new MutationObserver(syncTheme).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
 SOURCE
 const supported=['overview','power','schedule','bracket','nfl','rosters','trades','calculator','waivers','commissioner','players','dashboard','utilization','positionsos','compare','format'];
 this.navigate=tool=>{if(!supported.includes(tool))tool='overview';labTab=tool;root.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===tool)));if(data)draw()};
 root.querySelector('#labNav').addEventListener('click',e=>{if(e.target.closest('[data-tool]'))history.replaceState(null,'','#research/'+labTab)});
 this.navigate(location.hash.split('/')[1]||'overview');
 }
}
customElements.define('amfl-research',AMFLResearch);
let element;
window.amflMountResearch=target=>{if(!target)return;element ||= document.createElement('amfl-research');target.appendChild(element);element.navigate?.(location.hash.split('/')[1]||'overview')};
window.amflMountResearch(document.querySelector('#researchMount'));
})();
'''.replace('VERSION',VERSION).replace('MARKUP',json.dumps(markup)).replace(' SOURCE',source)
(ROOT/'research.js').write_text(code)
css=(ROOT/'analytics.css').read_text().replace(':root',':host').replace('body.light','.research-shell.light').replace('body{','.research-shell{')
css+='''
:host{display:block;--bg:#06142b;--panel:#0c2244;--line:#344e76;--text:#f7f9fd;--muted:#b8c8df;--gold:#e0b354;--red:#c82735;--blue:#286acb;font:16px/1.55 system-ui,sans-serif}
.research-shell{background:transparent}main{max-width:none;padding:4px 0 24px}.eyebrow{color:var(--gold)}h1{font-size:clamp(34px,5vw,54px)}.labnav button[aria-pressed="true"],.subcontrols button[aria-pressed="true"],.research-shell.light .labnav button[aria-pressed="true"],.research-shell.light .subcontrols button[aria-pressed="true"]{background:var(--red);color:#fff;border-color:var(--red)}.card{border-top-color:var(--blue)}.card:nth-child(2){border-top-color:var(--red)}.card:nth-child(3){border-top-color:var(--gold)}.team-link{text-decoration:underline;text-decoration-color:color-mix(in srgb,var(--gold) 35%,transparent);white-space:normal}.team-link small{display:block;font-weight:500;color:var(--muted);font-size:13px}.powerstack{height:8px;display:flex;background:var(--bg);min-width:100px;border-radius:6px;overflow:hidden;margin-top:6px}.legendChip{display:inline-block;width:13px;height:13px;border-radius:3px}.bracketScroll{overflow:auto;margin-top:24px}.bracketGrid{display:grid;grid-template-columns:1.1fr 1.1fr 1.1fr .9fr;gap:22px;min-width:950px;padding:10px 4px}.round{display:flex;flex-direction:column;gap:18px}.round h3{font-size:14px;letter-spacing:1px;text-transform:uppercase;margin:0 0 10px;color:var(--muted)}.bracketMatch{border:1px solid var(--line);border-radius:10px;position:relative}.bracketSlot{display:grid;grid-template-columns:22px 1fr auto;gap:7px;align-items:center;padding:10px 8px;background:var(--bg);font-size:13px}.bracketSlot+ .bracketSlot{border-top:1px solid var(--line)}.bracketSlot.chosen{background:color-mix(in srgb,var(--blue) 30%,var(--panel))}.bracketSlot button{padding:7px 5px;font-size:12px}.bracketSlot .team-link small{font-size:12px}.seed{font-weight:850;color:var(--gold)}.bye{border-left:4px solid var(--gold);padding:10px 12px;font-size:14px}.bye small{display:block;color:var(--muted)}.semifinals .bracketMatch{margin-top:53px}.semifinals .bracketMatch+ .bracketMatch{margin-top:119px}.finalround .bracketMatch{margin-top:185px}.bracketMatch:after{content:'';position:absolute;right:-23px;top:50%;width:22px;border-top:2px solid var(--blue)}.champion .champCard{margin-top:160px;border:2px solid var(--gold);border-radius:14px;background:linear-gradient(140deg,#183f79,#10244a);padding:22px 14px;text-align:center}.champCard>span{font-size:42px;display:block}.champCard p{font-size:13px;color:#d5e3f7}.outcomeFlow{display:block;width:100%;max-height:330px}.outcomeFlow text{font-size:15px;fill:var(--text)}.outcomeFlow .flowValue{font-size:13px;fill:var(--muted)}.flowHeader{font-size:18px;font-weight:800}.calculatorSide{padding:0;overflow:hidden}.calculatorHead{padding:20px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--blue) 12%,transparent)}.calculatorHead label{display:block;font-size:14px;color:var(--muted)}.calculatorHead select{display:block;width:100%;margin-top:8px}.calculatorSide>.playerfilter{width:calc(100% - 36px);margin:16px 18px}.calculatorSide .picklist{padding:0 18px;max-height:530px}.positionHeading{font-size:13px;color:var(--muted);letter-spacing:1px;border-bottom:1px solid var(--line);padding:10px 0}.calcPlayer small{font-size:12px}.calcPlayer .textbutton{font-weight:650;color:var(--text)}.calculatorFoot{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:16px 20px;border-top:1px solid var(--line);background:var(--bg);font-size:14px}.calculatorFoot .textbutton{margin-left:9px}.tradeSummarySide{min-width:0}.tradeSummarySide h3{border-bottom:1px solid var(--line);padding-bottom:14px}.miniStats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.miniStats>div{font-size:13px;color:var(--muted);background:var(--bg);padding:12px;border-radius:9px}.miniStats strong{display:block;font-size:24px;color:var(--text)}.miniStats small{display:block;font-size:12px}.miniStats .good{color:var(--green)}.miniStats .bad{color:var(--red)}.scenarioWin{border-left:3px solid var(--gold);padding:13px 16px;background:var(--bg);margin:16px 0}.scenarioWin span,.scenarioWin small{display:block;font-size:13px;color:var(--muted)}.scenarioWin strong{font-size:25px}.tradeVerdict{text-align:center;border-top:1px solid var(--line);padding:22px}.tradeVerdict>strong{font-size:22px;color:var(--gold)}.tradeSuggestions{background:color-mix(in srgb,var(--blue) 10%,var(--bg));border:1px dashed var(--line);border-radius:12px;padding:18px;margin-bottom:20px}.tradeSuggestions button{margin:5px}.research-shell.light{--bg:#f0f4fb;--panel:#fff;--line:#c5d3e6;--red:#b72839;--blue:#245db3;--gold:#94600c}.research-shell.light .champCard{background:#e8f0ff}.research-shell.light .champCard p{color:#425976}td>small{display:block;font-size:13px;color:var(--muted)}
@media(max-width:700px){main{padding:0}.miniStats{gap:6px}.miniStats>div{padding:9px}.miniStats strong{font-size:20px}.calculatorFoot{flex-wrap:wrap}.controls{gap:12px}.controls label{flex-wrap:wrap}.controls select{max-width:100%}.controls label:has(#manager){width:100%}.controls #manager{width:100%}.card small{font-size:13px}.outcomeFlow{min-width:570px}.panel:has(.outcomeFlow){overflow:auto}}
'''
css+='\n'+(ROOT/'research-responsive.css').read_text()
(ROOT/'research.css').write_text(css)
(ROOT/'analytics.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=/#research"><title>AMFL Research</title></head><body><p><a href="/#research">Open Research in the AMFL website</a></p><script>location.replace("/#research")</script></body></html>\n')
print('Built research.js and research.css')
